import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Categorical-Variable-Basics.md","filePath":"manual-zh/CTABLES-Categorical-Variable-Basics.md","lastUpdated":1785684581000}'),o={name:"manual-zh/CTABLES-Categorical-Variable-Basics.md"};function h(n,t,l,i,s,E){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_15-7-1-1-分类变量" tabindex="-1">15.7.1.1 分类变量 <a class="header-anchor" href="#_15-7-1-1-分类变量" aria-label="Permalink to &quot;15.7.1.1 分类变量&quot;">​</a></h4><p>命名一个分类变量的轴表达式会按该变量的值将数据划分到各个单元格。当 <code>TABLE</code> 上命名的所有变量都是分类变量时，默认每个单元格显示其包含的个案数，因此只指定一个变量会得到一个频数表，类似于 <code>FREQUENCIES</code> 命令的输出（参见 <a href="./FREQUENCIES">FREQUENCIES</a>）：</p><pre><code>CTABLES /TABLE=ageGroup.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>Age group</td><td>15 or younger</td><td>0</td></tr><tr><td>16 to 25</td><td>1099</td><td></td></tr><tr><td>26 to 35</td><td>967</td><td></td></tr><tr><td>36 to 45</td><td>1037</td><td></td></tr><tr><td>46 to 55</td><td>1175</td><td></td></tr><tr><td>56 to 65</td><td>1247</td><td></td></tr><tr><td>66 or older</td><td>1474</td><td></td></tr></tbody></table><p>指定一个行分类变量和一个列分类变量会得到一个列联表，类似于 <code>CROSSTABS</code> 命令的输出（参见 <a href="./CROSSTABS">CROSSTABS</a>）：</p><pre><code>CTABLES /TABLE=ageGroup BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Count</td><td>Count</td></tr><tr><td>Age group</td><td>15 or younger</td><td>0</td><td>0</td></tr><tr><td>16 to 25</td><td>594</td><td>505</td><td></td></tr><tr><td>26 to 35</td><td>476</td><td>491</td><td></td></tr><tr><td>36 to 45</td><td>489</td><td>548</td><td></td></tr><tr><td>46 to 55</td><td>526</td><td>649</td><td></td></tr><tr><td>56 to 65</td><td>516</td><td>731</td><td></td></tr><tr><td>66 or older</td><td>531</td><td>943</td><td></td></tr></tbody></table><p>‘&gt;’“嵌套”运算符将多个变量嵌套在单个轴上，例如：</p><pre><code>CTABLES /TABLE likelihoodOfBeingStoppedByPolice BY ageGroup &gt; gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th>Yes</th><th>No</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td>86. In the past year, have you hosted a social event or party where alcohol was served to adults?</td><td></td></tr><tr><td></td><td></td><td></td><td></td><td>Count</td><td>Count</td></tr><tr><td>Age group</td><td>15 or younger</td><td>S3a. GENDER:</td><td>Male</td><td>0</td><td>0</td></tr><tr><td>Female</td><td>0</td><td>0</td><td></td><td></td><td></td></tr><tr><td>16 to 25</td><td>S3a. GENDER:</td><td>Male</td><td>208</td><td>386</td><td></td></tr><tr><td>Female</td><td>202</td><td>303</td><td></td><td></td><td></td></tr><tr><td>26 to 35</td><td>S3a. GENDER:</td><td>Male</td><td>225</td><td>251</td><td></td></tr><tr><td>Female</td><td>242</td><td>249</td><td></td><td></td><td></td></tr><tr><td>36 to 45</td><td>S3a. GENDER:</td><td>Male</td><td>223</td><td>266</td><td></td></tr><tr><td>Female</td><td>240</td><td>307</td><td></td><td></td><td></td></tr><tr><td>46 to 55</td><td>S3a. GENDER:</td><td>Male</td><td>201</td><td>325</td><td></td></tr><tr><td>Female</td><td>282</td><td>366</td><td></td><td></td><td></td></tr><tr><td>56 to 65</td><td>S3a. GENDER:</td><td>Male</td><td>196</td><td>320</td><td></td></tr><tr><td>Female</td><td>279</td><td>452</td><td></td><td></td><td></td></tr><tr><td>66 or older</td><td>S3a. GENDER:</td><td>Male</td><td>162</td><td>367</td><td></td></tr><tr><td>Female</td><td>243</td><td>700</td><td></td><td></td><td></td></tr></tbody></table><p>‘+’“堆叠”运算符允许单个输出表包含多个数据分析。使用 ‘+’ 时，<code>CTABLES</code> 将输出表划分为多个 <em>sections</em>（节），每节都包含对完整数据集的一次分析。例如，以下命令分别按性别对年龄组和驾驶频率制表：</p><pre><code>CTABLES /TABLE ageGroup + freqOfDriving BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Count</td><td>Count</td></tr><tr><td>Age group</td><td>15 or younger</td><td>0</td><td>0</td></tr><tr><td>16 to 25</td><td>594</td><td>505</td><td></td></tr><tr><td>26 to 35</td><td>476</td><td>491</td><td></td></tr><tr><td>36 to 45</td><td>489</td><td>548</td><td></td></tr><tr><td>46 to 55</td><td>526</td><td>649</td><td></td></tr><tr><td>56 to 65</td><td>516</td><td>731</td><td></td></tr><tr><td>66 or older</td><td>531</td><td>943</td><td></td></tr><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>2305</td><td>2362</td></tr><tr><td>Several days a week</td><td>440</td><td>834</td><td></td></tr><tr><td>Once a week or less</td><td>125</td><td>236</td><td></td></tr><tr><td>Only certain times a year</td><td>58</td><td>72</td><td></td></tr><tr><td>Never</td><td>192</td><td>348</td><td></td></tr></tbody></table><p>当 ‘+’ 和 ‘&gt;’ 一起使用时，‘&gt;’ 的绑定更紧密。可使用括号覆盖运算符优先级。因此：</p><pre><code>CTABLES /TABLE hasConsideredReduction + hasBeenCriticized &gt; gender.
CTABLES /TABLE (hasConsideredReduction + hasBeenCriticized) &gt; gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>26. During the last 12 months, has there been a time when you felt you should cut down on your drinking?</td><td>Yes</td><td>513</td><td></td><td></td></tr><tr><td>No</td><td>3710</td><td></td><td></td><td></td></tr><tr><td>27. During the last 12 months, has there been a time when people criticized your drinking?</td><td>Yes</td><td>S3a. GENDER:</td><td>Male</td><td>135</td></tr><tr><td>Female</td><td>49</td><td></td><td></td><td></td></tr><tr><td>No</td><td>S3a. GENDER:</td><td>Male</td><td>1916</td><td></td></tr><tr><td>Female</td><td>2126</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td>Count</td></tr><tr><td>26. During the last 12 months, has there been a time when you felt you should cut down on your drinking?</td><td>Yes</td><td>S3a. GENDER:</td><td>Male</td><td>333</td></tr><tr><td>Female</td><td>180</td><td></td><td></td><td></td></tr><tr><td>No</td><td>S3a. GENDER:</td><td>Male</td><td>1719</td><td></td></tr><tr><td>Female</td><td>1991</td><td></td><td></td><td></td></tr><tr><td>27. During the last 12 months, has there been a time when people criticized your drinking?</td><td>Yes</td><td>S3a. GENDER:</td><td>Male</td><td>135</td></tr><tr><td>Female</td><td>49</td><td></td><td></td><td></td></tr><tr><td>No</td><td>S3a. GENDER:</td><td>Male</td><td>1916</td><td></td></tr><tr><td>Female</td><td>2126</td><td></td><td></td><td></td></tr></tbody></table>`,16)])])}const p=d(o,[["render",h]]);export{u as __pageData,p as default};
